// Fallback path untuk icon tanpa path terdefinisi
const defaultPath = 'M12 6.042A8.967 8.967 0 006 3.75c-1.052 0-2.062.18-3 .512v14.25A8.987 8.987 0 016 18c2.305 0 4.408.867 6 2.292m0-14.25a8.966 8.966 0 016-2.292c1.052 0 2.062.18 3 .512v14.25A8.987 8.987 0 0118 18a8.967 8.967 0 00-6 2.292m0-14.25v14.25';

let selectedIcon = document.getElementById('icon-value').value || 'book-open';

function renderGrid(list) {
  const grid = document.getElementById('icon-grid');
  grid.innerHTML = list.map(name => `
    <button type="button" onclick="selectIcon('${name}')" title="${name}"
            class="flex items-center justify-center p-2 rounded-lg hover:bg-white
                   hover:shadow-sm transition-all ${selectedIcon === name ? 'bg-teal-50 ring-2 ring-teal-500' : ''}"
            id="icon-btn-${name.replace(/\s/g,'-')}">
      <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24"
           stroke-width="1.5" stroke="currentColor" class="w-5 h-5 ${selectedIcon === name ? 'text-teal-600' : 'text-slate-500'}">
        <path stroke-linecap="round" stroke-linejoin="round"
              d="${svgPaths[name] || defaultPath}"/>
      </svg>
    </button>
  `).join('');
}

function selectIcon(name) {
  selectedIcon = name;
  document.getElementById('icon-value').value = name;
  document.querySelector('#icon-preview-svg path').setAttribute('d', svgPaths[name] || defaultPath);
  document.getElementById('icon-picker-panel').classList.add('hidden');
  renderGrid(icons);
}

function filterIcons(query) {
  const filtered = icons.filter(n => n.includes(query.toLowerCase()));
  renderGrid(filtered);
}

// Initial render
document.addEventListener('DOMContentLoaded', () => {
    document.querySelector('#icon-preview-svg path').setAttribute('d', svgPaths[selectedIcon] || defaultPath);
    renderGrid(icons);
});
</script>
@endpush
